'use strict';
const $=s=>document.querySelector(s),escape=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let model,queryTypes=[],worker=null,deviceReport=null;
function types(){const candidates=model.ranges?model.ranges[0]:model.cases.map(c=>c.players[0]);const map=new Map();for(const p of candidates){const k=JSON.stringify([p.hand,p.remaining,p.observations]);if(!map.has(k))map.set(k,p);}queryTypes=[...map.values()];$('#query').innerHTML=queryTypes.map((p,i)=>'<option value="'+i+'">Hand '+escape(p.hand.join(' '))+' · deck remaining '+escape(p.remaining.join(' '))+(p.observations?' · private history '+(i+1):'')+'</option>').join('');}
function load(){try{model=SnapRanges.example($('#example').value);$('#model').value=JSON.stringify(model,null,2);types();$('#scope').textContent=model.beliefScope||'Explicit private ranges';$('#status').textContent='Ready';}catch(e){$('#status').textContent=e.message;}}
function metric(name,value){return '<div><dt>'+escape(name)+'</dt><dd>'+escape(value)+'</dd></div>';}
function stats(s,elapsed){const d=s.diagnostics;$('#metrics').innerHTML=metric('Computation',(elapsed/1000).toFixed(2)+' s')+metric('Iterations',s.iterations.toLocaleString())+metric('Information states',s.informationStates.toLocaleString())+metric('Nash gap',d.nashGap===null?'Unmeasured':d.nashGap.toFixed(5))+metric('Worst root-type gain',d.maxConditionalGain===null?'Unmeasured':d.maxConditionalGain.toFixed(5))+metric('Numeric table only',(s.numericTableBytes/1048576).toFixed(2)+' MiB');}
function start(){if(worker)worker.terminate();worker=new Worker('./solver/worker.js?v=1');worker.onerror=e=>{$('#status').textContent='Worker error: '+e.message;};worker.onmessage=event=>{const m=event.data;if(m.type==='progress'){stats(m.stats,m.elapsedMs);$('#status').textContent='Computing · '+m.stats.algorithm;}else if(m.type==='evaluating')$('#status').textContent='Evaluating action EVs';else if(m.type==='result'){stats(m.stats,m.solveWallMs);$('#status').textContent=m.analysis.strategyValidated?'Accuracy target reached':'Provisional · accuracy target not established';$('#scope').textContent=m.modelScope;$('#certificate').textContent=m.analysis.strategyValidated?'Measured deviation bounds apply to this configured continuation game.':'All move assessments remain provisional. '+(m.stats.diagnostics.reason||'Continue analysis to improve the measured gap.');$('#actions').innerHTML=m.analysis.actions.slice().sort((a,b)=>b.frequency-a.frequency||b.ev-a.ev).map(a=>'<tr><td>'+escape(SnapSolver.label(a.action))+'</td><td>'+(100*a.frequency).toFixed(1)+'%</td><td>'+a.ev.toFixed(4)+'</td><td>'+a.evLoss.toFixed(4)+'</td><td class="grade-'+a.grade+'">'+a.grade+'</td></tr>').join('');$('#details').textContent=JSON.stringify({algorithm:m.stats.algorithm,cacheHit:m.cached,cacheSaved:m.cacheSaved,cacheError:m.cacheError,checkpointBytes:m.checkpointBytes,evaluation:m.analysis.evaluation,actions:m.analysis.actions.map(a=>({turn:SnapSolver.label(a.action),win:a.wdl[0],draw:a.wdl[1],loss:a.wdl[2],evError95:a.error95,evLossInterval:a.lossInterval}))},null,2);}else if(m.type==='error')$('#status').textContent=m.message;else if(m.type==='benchmark-case')$('#status').textContent='Benchmarking '+m.name;else if(m.type==='benchmark-progress')deviceTable(m.results);else if(m.type==='benchmark-result'){deviceReport=m;deviceTable(m.results);$('#download').disabled=false;$('#status').textContent='Browser benchmark complete';}};return worker;}
function deviceTable(rows){$('#device-results').hidden=false;$('#device-table').innerHTML='<div class="table-scroll"><table><tr><th>Position</th><th>First run</th><th>Warm</th><th>Target reached</th></tr>'+rows.map(r=>'<tr><td>'+escape(r.name)+(r.coldWasCached?' (cached)':'')+'</td><td>'+Math.round(r.coldMs)+' ms</td><td>'+(r.warmMs===null?'Unavailable':Math.round(r.warmMs)+' ms')+'</td><td>'+(r.converged?'Yes':'Unestablished')+'</td></tr>').join('')+'</table></div>';}
$('#example').addEventListener('change',load);
$('#apply').addEventListener('click',()=>{try{model=JSON.parse($('#model').value);SnapSolver.normalizeModel(model);types();$('#scope').textContent=model.beliefScope||'Explicit private ranges';$('#status').textContent='Model applied';}catch(e){$('#status').textContent=e.message;}});
$('#solve').addEventListener('click',()=>{try{const selected=Number($('#query').value)||0;model=JSON.parse($('#model').value);SnapSolver.normalizeModel(model);types();$('#query').value=String(Math.min(selected,queryTypes.length-1));const query=queryTypes[Number($('#query').value)||0];start().postMessage({type:'solve',model,query,maxMs:Number($('#budget').value)*1000,targetGap:Number($('#target').value),cache:true});$('#status').textContent='Initializing';}catch(e){$('#status').textContent=e.message;}});
$('#stop').addEventListener('click',()=>{if(worker)worker.terminate();worker=null;$('#status').textContent='Stopped';});
$('#device').addEventListener('click',()=>{deviceReport=null;$('#download').disabled=true;start().postMessage({type:'benchmark'});$('#status').textContent='Starting browser benchmark';});
$('#download').addEventListener('click',()=>{if(!deviceReport)return;const url=URL.createObjectURL(new Blob([JSON.stringify(deviceReport,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='theoretical-snap-browser-benchmark.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
load();
